public record BrokerScore(
    string Name,
    int DeliverySemantics,
    int Throughput,
    int Ordering,
    int OperationalModel,
    int Retention,
    int Total => DeliverySemantics + Throughput + Ordering + OperationalModel + Retention
)
{
    public static BrokerScore Evaluate(string name, Action<BrokerScore> configure)
    {
        var score = new BrokerScore(name, 0, 0, 0, 0, 0);
        configure(score);
        return score;
    }
}

// Usage
var rabbit = BrokerScore.Evaluate("RabbitMQ", s =>
{
    s.DeliverySemantics = 4;
    s.Throughput = 3;
    s.Ordering = 3;
    s.OperationalModel = 2;
    s.Retention = 2;
});
Console.WriteLine($"{rabbit.Name}: {rabbit.Total}/25");
